  TABS.forEach(function (t) { t.items.forEach(function (it, i) { it.code = t.code + "-" + (i < 9 ? "0" : "") + (i + 1); }); });
  function findService(value) {
    var parts = String(value || "").split(":"), tab = null, item = null;
    TABS.forEach(function (t) { if (t.id === parts[0]) tab = t; });
    if (tab && parts[1]) tab.items.forEach(function (it) { if (it.id === parts[1]) item = it; });
    return { tab: tab, item: item };
  }

